/* ── Rotating Wheel Dial ── */
function WheelDial({ value, onChange, max, labelColor }) {
  const ref = useRef(null);
  const dragging = useRef(false);
  const lastY = useRef(0);
  const rawVal = useRef(value);
  const velocity = useRef(0);
  const [h, setH] = useState(400);
  const [displayVal, setDisplayVal] = useState(value);
  const animRef = useRef(null);

  // Sync rawVal if value changes externally (e.g. from keyboard input)
  useEffect(() => {
    if (Math.abs(rawVal.current - value) > 1.5) {
      rawVal.current = value;
      velocity.current = 0;
    }
  }, [value]);

  const R = 168;
  const wheelCx = 438;
  const wheelCy = h / 2 - 24;
  const DEG_PER_UNIT = 2.28;
  const indicatorAngle = 180;
  const FRICTION = 0.96;
  const OVERSHOOT_MAX = 200; // max overshoot in units
  const SPRING = 0.033; // spring-back strength

  useEffect(() => {
    const animate = () => {
      // Apply momentum
      if (Math.abs(velocity.current) > 0.05) {
        rawVal.current += velocity.current;
        velocity.current *= FRICTION;
      } else {
        velocity.current = 0;
      }

      // Spring-back if out of bounds
      if (rawVal.current < 0) {
        rawVal.current += (-rawVal.current) * SPRING;
        velocity.current *= 0.5;
        if (rawVal.current > -0.1) rawVal.current = 0;
      } else if (rawVal.current > max) {
        rawVal.current -= (rawVal.current - max) * SPRING;
        velocity.current *= 0.5;
        if (rawVal.current < max + 0.1) rawVal.current = max;
      }

      // Clamp overshoot
      rawVal.current = Math.max(-OVERSHOOT_MAX, Math.min(max + OVERSHOOT_MAX, rawVal.current));

      const clamped = Math.max(0, Math.min(max, rawVal.current));
      const snapped = Math.round(clamped / STP) * STP;
      onChange(snapped);

      // displayVal follows rawVal (unclamped) for elastic visual
      setDisplayVal(prev => {
        const diff = rawVal.current - prev;
        if (Math.abs(diff) < 0.05) return rawVal.current;
        return prev + diff * 0.12;
      });

      animRef.current = requestAnimationFrame(animate);
    };
    animRef.current = requestAnimationFrame(animate);
    return () => cancelAnimationFrame(animRef.current);
  }, [value, max, onChange]);

  useEffect(() => {
    if (!ref.current) return;
    setH(ref.current.offsetHeight);
    const ro = new ResizeObserver(entries => { for (const e of entries) setH(e.contentRect.height); });
    ro.observe(ref.current);
    return () => ro.disconnect();
  }, []);

  const onDown = (e) => {
    e.preventDefault();
    dragging.current = true;
    lastY.current = e.clientY;
    velocity.current = 0;
  };

  useEffect(() => {
    const onMove = (e) => {
      if (!dragging.current) return;
      const deltaY = e.clientY - lastY.current;
      lastY.current = e.clientY;
      const deltaVal = deltaY / 10;
      // Allow overshoot with resistance at boundaries
      const next = rawVal.current + deltaVal;
      if (next < 0 || next > max) {
        rawVal.current += deltaVal * 0.3; // resistance
      } else {
        rawVal.current = next;
      }
      velocity.current = deltaVal * 0.5;
      const snapped = Math.round(rawVal.current / STP) * STP;
      onChange(snapped);
    };
    const onUp = () => { dragging.current = false; };
    window.addEventListener("pointermove", onMove);
    window.addEventListener("pointerup", onUp);
    return () => { window.removeEventListener("pointermove", onMove); window.removeEventListener("pointerup", onUp); };
  }, [max, onChange]);

  const onWheel = (e) => {
    e.preventDefault();
    velocity.current += e.deltaY / 350;
  };

  const visibleRange = Math.ceil(140 / DEG_PER_UNIT);
  const vMin = Math.floor((displayVal - visibleRange) / 2) * 2;
  const vMax = Math.ceil((displayVal + visibleRange) / 2) * 2;

  const screenAngle = (v) => indicatorAngle + (v - displayVal) * DEG_PER_UNIT;
  const cx = (a, r) => wheelCx + r * Math.cos((a * Math.PI) / 180);
  const cy = (a, r) => wheelCy + r * Math.sin((a * Math.PI) / 180);

  const ticks = [];
  for (let v = vMin; v <= vMax; v += 2) {
    if (v < 0 || v > max + 40) continue;
    const isMajor = v % 10 === 0;
    const inRange = v >= 0 && v <= max;
    ticks.push({ v, isMajor, inRange });
  }

  return (
    <div ref={ref} style={{ position:"absolute", top:0, right:0, bottom:0, width:"100%", touchAction:"none", cursor:"ns-resize" }} onPointerDown={onDown} onWheel={onWheel}>
      {/* Layer 1 — Labels (lowest z) */}
      <svg style={{ position:"absolute", top:0, left:0, width:"100%", height:"100%", overflow:"visible", zIndex:1 }}>
        {ticks.map((t, i) => {
          if (!t.isMajor || !t.inRange) return null;
          const a = screenAngle(t.v);
          const lx = cx(a, R + 42), ly = cy(a, R + 42);
          return (
            <text key={`l${i}`} x={lx} y={ly} textAnchor="end" dominantBaseline="central"
              transform={`rotate(${a + 180} ${lx} ${ly})`}
              style={{ fontFamily:fono, fontSize:18, fontWeight:500, fill:labelColor || P.inchiostro, opacity:0.7, transition:"fill 400ms ease" }}>
              {t.v}
            </text>
          );
        })}
      </svg>

      {/* Layer 3 — Wheel arc + ticks + dots (highest z) */}
      <svg style={{ position:"absolute", top:0, left:0, width:"100%", height:"100%", overflow:"visible", zIndex:3, pointerEvents:"none" }}>
        <circle cx={wheelCx} cy={wheelCy} r={R} fill="none" stroke={P.gesso} strokeWidth={58} />
        {ticks.map((t, i) => {
          const a = screenAngle(t.v);

          if (t.isMajor) {
            const ox = cx(a, R + 22), oy = cy(a, R + 22);
            const ix = cx(a, R + 9), iy = cy(a, R + 9);
            return (
              <line key={`t${i}`} x1={ox} y1={oy} x2={ix} y2={iy}
                stroke={P.inchiostro} strokeWidth={1.5}
                opacity={t.inRange ? 0.8 : 0.15}
                strokeLinecap="butt" />
            );
          } else {
            const dx = cx(a, R + 21), dy = cy(a, R + 21);
            return (
              <circle key={`d${i}`} cx={dx} cy={dy} r={1.3}
                fill={P.inchiostro} opacity={t.inRange ? 0.8 : 0.15} />
            );
          }
        })}
      </svg>
    </div>
  );
}

